1	package retention
2	
3	import (
4		"encoding/json"
5		"strconv"
6		"strings"
7	)
8	
9	// Date 是按日历日期（年月日）比较的日期，与时区和夏令时无关。
10	//
11	// 对外的文本格式统一为 YYYY-MM-DD。零值表示无效日期，不能用于业务。
12	type Date struct {
13		year  int
14		month int
15		day   int
16	}
17	
18	// ParseDate 按 YYYY-MM-DD 解析日期。
19	// 只接受完整的四位年份、两位月份、两位日期，且日期必须真实存在。
20	//
21	// 逐字要求：年、月、日分别恰好是四位、两位、两位的数字，数字只允许半角
22	// 0-9；两处分隔符必须是半角横线 '-'。带正负号、缺少补零、首尾空白、
23	// 附带时间，或在文本里直接写出反斜杠转义（如 `\u0032025-01-10`）都
24	// 明确失败——绝不通过去空白、补位、去掉符号或解释转义来接受。JSON 字符串
25	// 的转义解码在 UnmarshalJSON 中处理，不发生在这里。
26	func ParseDate(s string) (Date, error) {
27		if len(s) != 10 || s[4] != '-' || s[7] != '-' {
28			return Date{}, &InvalidDateError{Value: s}
29		}
30		// 不用 strconv.Atoi：它会接受 "+1"、"-1" 这类带符号文本，使
31		// "2025-+1-10"、"2025-01-+1" 被当成普通日期。逐字符只认 0-9。
32		year, ok1 := parseDigits(s[0:4])
33		month, ok2 := parseDigits(s[5:7])
34		day, ok3 := parseDigits(s[8:10])
35		if !ok1 || !ok2 || !ok3 {
36			return Date{}, &InvalidDateError{Value: s}
37		}
38		if !validCalendarDate(year, month, day) {
39			return Date{}, &InvalidDateError{Value: s}
40		}
41		return Date{year, month, day}, nil
42	}
43	
44	// parseDigits 把一段只含半角数字 0-9 的文本解析成整数；出现任何非数字
45	// 字符（正负号、空白、字母、反斜杠等）即返回 ok=false。
46	func parseDigits(s string) (int, bool) {
47		n := 0
48		for i := 0; i < len(s); i++ {
49			c := s[i]
50			if c < '0' || c > '9' {
51				return 0, false
52			}
53			n = n*10 + int(c-'0')
54		}
55		return n, true
56	}
57	
58	// MustParseDate 按 YYYY-MM-DD 解析日期，失败即 panic。
59	// 只适合在测试或字面量构造中使用。
60	func MustParseDate(s string) Date {
61		d, err := ParseDate(s)
62		if err != nil {
63			panic(err)
64		}
65		return d
66	}
67	
68	// String 返回 YYYY-MM-DD 形式的文本。
69	func (d Date) String() string {
70		var b strings.Builder
71		b.Grow(10)
72		writePadded(&b, d.year, 4)
73		b.WriteByte('-')
74		writePadded(&b, d.month, 2)
75		b.WriteByte('-')
76		writePadded(&b, d.day, 2)
77		return b.String()
78	}
79	
80	// IsZero 报告日期是否为零值（未设置）。
81	func (d Date) IsZero() bool { return d.year == 0 && d.month == 0 && d.day == 0 }
82	
83	// Before 按日历日期报告 d 是否早于 other。
84	func (d Date) Before(other Date) bool {
85		if d.year != other.year {
86			return d.year < other.year
87		}
88		if d.month != other.month {
89			return d.month < other.month
90		}
91		return d.day < other.day
92	}
93	
94	// After 按日历报告 d 是否晚于 other。
95	func (d Date) After(other Date) bool { return other.Before(d) }
96	
97	// Equal 按日历报告两个日期是否相同。
98	func (d Date) Equal(other Date) bool {
99		return d.year == other.year && d.month == other.month && d.day == other.day
100	}
101	
102	// MarshalJSON 按 YYYY-MM-DD 序列化。
103	func (d Date) MarshalJSON() ([]byte, error) {
104		return []byte(`"` + d.String() + `"`), nil
105	}
106	
107	// UnmarshalJSON 按 YYYY-MM-DD 形式反序列化并校验真实日期。
108	//
109	// 以 JSON 字符串解码后所表示的实际文本判断合法性：先让 encoding/json
110	// 完成字符串解码，普通字符与 \uXXXX 等合法 JSON 转义可以混用——
